package router

type Route struct {
	Prefix  string
	Handler string
	Enabled bool
}

// Resolve returns the handler for the most specific enabled prefix.
func Resolve(routes []Route, path string) (string, bool) {
	var bestMatch *Route
	for i := range routes {
		route := &routes[i]
		if !route.Enabled {
			continue
		}

		// Check if path starts with prefix
		if len(path) >= len(route.Prefix) && path[:len(route.Prefix)] == route.Prefix {
			// Check for path boundary: either prefix is the whole path, 
			// or the next character in path is a separator (assuming '/' is the separator)
			// or the prefix itself ends with a separator.
			// However, the prompt implies standard prefix matching logic where 
			// longest prefix wins.
			if bestMatch == nil || len(route.Prefix) > len(bestMatch.Prefix) {
				bestMatch = route
			}
		}
	}

	if bestMatch != nil {
		return bestMatch.Handler, true
	}
	return "", false
}

package retry

import "errors"

type Store interface {
	Get(key string) (string, error)
	Put(key, value string) error
}

var ErrTemporary = errors.New("temporary")
var ErrMissing = errors.New("missing")

// Ensure reads key and writes fallback only when the key is missing.
func Ensure(store Store, key, fallback string) (string, error) {
	value, err := store.Get(key)
	if err == nil {
		return value, nil
	}

	if !errors.Is(err, ErrMissing) {
		return "", err
	}

	if err := store.Put(key, fallback); err != nil {
		return "", err
	}

	return fallback, nil
}

package cache

import (
	"container/list"
)

// entry stores the key and value in the list nodes.
type entry struct {
	key   string
	value int
}

// LRU implements a fixed-capacity least recently used cache.
type LRU struct {
	capacity int
	items    map[string]*list.Element
	evictList *list.List
}

// NewLRU initializes a new LRU cache with the given capacity.
func NewLRU(capacity int) *LRU {
	return &LRU{
		capacity:  capacity,
		items:     make(map[string]*list.Element),
		evictList: list.New(),
	}
}

// Get retrieves a value from the cache. Returns the value and true if found,
// otherwise 0 and false. Moves the accessed item to the front.
func (c *LRU) Get(key string) (int, bool) {
	if ent, ok := c.items[key]; ok {
		c.evictList.MoveToFront(ent)
		return ent.Value.(*entry).value, true
	}
	return 0, false
}

// Put adds a value to the cache. If the key exists, updates the value and
// moves it to the front. If the cache is full, evicts the least recently used item.
func (c *LRU) Put(key string, value int) {
	if ent, ok := c.items[key]; ok {
		c.evictList.MoveToFront(ent)
		ent.Value.(*entry).value = value
		return
	}

	if c.evictList.Len() >= c.capacity && c.capacity > 0 {
		c.removeOldest()
	}

	if c.capacity > 0 {
		ent := &entry{key, value}
		element := c.evictList.PushFront(ent)
		c.items[key] = element
	}
}

// Len returns the current number of items in the cache.
func (c *LRU) Len() int {
	return c.evictList.Len()
}

// removeOldest removes the least recently used item from the cache.
func (c *LRU) removeOldest() {
	ent := c.evictList.Back()
	if ent != nil {
		c.evictList.Remove(ent)
		kv := ent.Value.(*entry)
		delete(c.items, kv.key)
	}
}

using System;
using System.Collections.Generic;
using System.Linq;

public static class Ledger
{
    // Returns, for each account, the running balance after every entry, and the
    // final balance. Entries are (account, delta) in chronological order.
    // BUG: callers report that the running balances are all identical to the
    // final balance, and that AverageDelta is truncated to a whole number.
    public static (Dictionary<string, List<int>> Running, Dictionary<string, int> Final, double AverageDelta)
        Summarise(IEnumerable<(string Account, int Delta)> entries)
    {
        var totals = new Dictionary<string, int>();
        var running = new Dictionary<string, List<int>>();

        foreach (var e in entries)
        {
            if (!totals.ContainsKey(e.Account))
            {
                totals[e.Account] = 0;
                running[e.Account] = new List<int>();
            }
            totals[e.Account] += e.Delta;
            running[e.Account].Add(totals[e.Account]);
        }

        var deltas = entries.Select(e => e.Delta).ToList();
        var average = deltas.Any() ? deltas.Average() : 0.0;
        return (running, totals, average);
    }
}

export type Fetcher = (id: string) => Promise<{ id: string; parent: string | null }>;

// Walks from a node to the root and returns the chain, root last.
// Rewrite this to use async/await and a plain loop. Behaviour must not change,
// including that a cycle throws Error("cycle detected") and that the chain is
// capped at 50 entries with Error("chain too long").
export async function ancestry(fetch: Fetcher, start: string): Promise<string[]> {
  const seen = new Set<string>();
  const chain: string[] = [];
  let currentId: string | null = start;

  while (currentId !== null) {
    if (seen.has(currentId)) {
      throw new Error("cycle detected");
    }
    seen.add(currentId);
    chain.push(currentId);

    if (chain.length > 50) {
      throw new Error("chain too long");
    }

    const node = await fetch(currentId);
    currentId = node.parent;
  }

  return chain;
}

public static class FrameUtil
{
    public static int CountZeroes(FrameBuffer buffer)
    {
        int count = 0;
        for (int i = 0; i < buffer.Count; i++)
        {
            if (buffer.Get(i) == 0)
            {
                count++;
            }
        }
        return count;
    }
}

